        ("extend", "list.extend adds every item from another iterable.", "a = [1]\na.extend([2, 3])\nprint(a)", "[1, 2, 3]", "list"),
        ("insert", "list.insert places an item at an index.", "a = ['b']\na.insert(0, 'a')\nprint(a)", "['a', 'b']", "index"),
        ("pop method", "list.pop removes and returns an item, the last one by default.", "a = [1, 2]\nprint(a.pop(), a)", "2 [1]", "list"),
