        ("update", "dict.update copies pairs in from another mapping.", "d = {'a': 1}\nd.update({'b': 2})\nprint(sorted(d))", "['a', 'b']"),
        ("setdefault", "setdefault stores a value only when the key is missing.", "d = {}\nprint(d.setdefault('a', 1), d['a'])", "1 1", "dictionary"),
        ("tuple unpacking", "A tuple of names on the left receives a sequence on the right.", "lat, lon = (6.9, 79.8)\nprint(lon)", "79.8", "unpacking"),
        ("named field", "A tuple can be documented by unpacking into meaningful names.", "name, pop = ('Kandy', 125)\nprint(name)", "Kandy", "tuple"),
        ("set literal", "A set of one or more items is written with curly braces.", "print(len({1, 1, 2}))", "2", "set"),
        ("set operations", "Sets support union, intersection, and difference with |, &, and -.", "print(sorted({1, 2} & {2, 3}))", "[2]", "set"),
        ("set add", "set.add inserts one item.", "s = {1}\ns.add(1)\ns.add(2)\nprint(sorted(s))", "[1, 2]", "set"),
        ("collection length", "len() reports how many items a container holds.", "print(len({'a': 1, 'b': 2}))", "2"),
        ("count method", "str.count and list.count tally how often a value appears.", "print('banana'.count('a'))", "3"),
        ("index method", "The index method returns the first position of a value.", "print(['a', 'b'].index('b'))", "1", "index"),
        ("join", "str.join glues pieces with a separator.", "print(', '.join(['Kandy', 'Galle']))", "Kandy, Galle", "string"),
        ("split", "str.split breaks text into a list.", "print('a,b'.split(','))", "['a', 'b']", "string"),
        ("strip", "str.strip removes whitespace from both ends.", "print('  hi  '.strip())", "hi", "string"),
        ("replace", "str.replace returns a new string with substrings swapped.", "print('cat'.replace('c', 'b'))", "bat", "string"),
        ("startswith", "startswith tests a prefix.", "print('EPSG:4326'.startswith('EPSG'))", "True", "string"),
        ("min builtin", "min() returns the smallest item.", "print(min([3, 1, 2]))", "1"),
        ("max builtin", "max() returns the largest item.", "print(max([3, 1, 2]))", "3"),
        ("sum builtin", "sum() adds numbers, starting from 0 by default.", "print(sum([1, 2, 3]))", "6"),
        ("nested list", "A list can hold other lists, which is a simple grid.", "grid = [[1, 2], [3, 4]]\nprint(grid[1][1])", "4", "list"),
