        ("heapq", "The heapq module keeps a list ordered as a binary heap so the smallest item is at index 0.", "import heapq\nh = [3, 1, 2]\nheapq.heapify(h)\nprint(heapq.heappop(h))", "1"),
        ("bisect", "The bisect module finds the insertion point that keeps a list sorted.", "import bisect\nprint(bisect.bisect_left([1, 3, 5], 3))", "1"),
