        ("late binding", "A closure looks up the loop variable when it is called, not when it was created, unless you bind it early.", "fs = [(lambda n=i: n) for i in range(3)]\nprint(fs[0]())", "0", "closure"),
        ("lambda body", "A lambda may contain only one expression, not statements.", "print((lambda x: x + 1)(4))", "5", "lambda"),
        ("docstring lookup", "help and __doc__ read the string written as the first statement of a function.", "def f():\n    'Adds nothing.'\n    return 1\nprint(f.__doc__)", "Adds nothing.", "docstring"),
        ("annotations dict", "A function stores its annotations on __annotations__.", "def f(n: int) -> int:\n    return n\nprint(f.__annotations__['n'].__name__)", "int", "type hint"),
        ("callable", "An object that can be called with parentheses, tested with callable().", "print(callable(len), callable(1))", "True False", "function"),
        ("__call__", "A method that lets an instance be called like a function.", "class A:\n    def __call__(self, n):\n        return n + 1\nprint(A()(3))", "4", "dunder method"),
