        ("variadic", "A function that accepts a variable number of arguments through *args or **kwargs.", "def f(*a):\n    return len(a)\nprint(f(1, 2, 3))", "3", "*args"),
        ("argument unpacking", "A * or ** in a call spreads a sequence or dict into arguments.", "def f(a, b):\n    return a + b\nprint(f(*[1, 2]))", "3", "*args"),
        ("default trap", "A mutable default argument is created once and shared by every call.", "def f(box=[]):\n    box.append(1)\n    return len(box)\nprint(f(), f())", "1 2", "default argument"),
        ("None as default", "Using None as a default avoids sharing a mutable object.", "def f(box=None):\n    box = [] if box is None else box\n    box.append(1)\n    return len(box)\nprint(f(), f())", "1 1", "default trap"),
